mapper.insert:
insert into cm_knowledge_profile(id,user_id,goal_id,knowledge_point_id,baseline_direct_ability,current_direct_ability,
    confidence_level,profile_status,distinct_question_count,last_direct_evidence_time,recent_trend,rule_version_id,calculated_time)
values(#{id},#{item.userId},#{item.goalId},#{knowledgePointId},50,
    (50*3+case when #{correct} then 85 else 25 end)/4,'low','provisional',1,now(),'stable',#{item.ruleVersionId},now())
on conflict(user_id,goal_id,knowledge_point_id) do update set
    current_direct_ability=(coalesce(cm_knowledge_profile.current_direct_ability,50)*3+
        case when #{correct} then 85 else 25 end)/4,
    distinct_question_count=(select count(*) from cm_learning_evidence e where e.user_id=#{item.userId}
        and e.goal_id=#{item.goalId} and e.knowledge_point_id=#{knowledgePointId}
        and e.is_valid=true and e.is_distinct_question=true),
    confidence_level=case when (select count(*) from cm_learning_evidence e where e.user_id=#{item.userId}
        and e.goal_id=#{item.goalId} and e.knowledge_point_id=#{knowledgePointId}
        and e.is_valid=true and e.is_distinct_question=true)<=1 then 'low' else 'medium' end,
    profile_status=case when (select count(*) from cm_learning_evidence e where e.user_id=#{item.userId}
        and e.goal_id=#{item.goalId} and e.knowledge_point_id=#{knowledgePointId}
        and e.is_valid=true and e.is_distinct_question=true)<=1 then 'provisional'
        when (coalesce(cm_knowledge_profile.current_direct_ability,50)*3+case when #{correct} then 85 else 25 end)/4<40 then 'urgent'
        when (coalesce(cm_knowledge_profile.current_direct_ability,50)*3+case when #{correct} then 85 else 25 end)/4<60 then 'weak'
        when (coalesce(cm_knowledge_profile.current_direct_ability,50)*3+case when #{correct} then 85 else 25 end)/4<75 then 'learning'
        when (coalesce(cm_knowledge_profile.current_direct_ability,50)*3+case when #{correct} then 85 else 25 end)/4<85 then 'proficient'
        else 'mastery_candidate' end,
    last_direct_evidence_time=now(),rule_version_id=#{item.ruleVersionId},calculated_time=now(),
    row_version=cm_knowledge_profile.row_version+1,update_time=now()

insert into cm_profile_change(id,profile_level,knowledge_profile_id,settlement_id,change_type,after_data,
    rule_version_id,request_id)
select #{id},'knowledge',p.id,#{settlementId},'answer',
       jsonb_build_object('schema_version','profile_change/1.0','ability',p.current_direct_ability,
                          'status',p.profile_status,'confidence',p.confidence_level),
       #{item.ruleVersionId},#{requestId}
  from cm_knowledge_profile p where p.user_id=#{item.userId} and p.goal_id=#{item.goalId}
   and p.knowledge_point_id=#{knowledgePointId}
on conflict(request_id) do nothing
